DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(45) NOT NULL,
  `password` text NOT NULL,
  `first_name` varchar(45) NOT NULL,
  `last_name` varchar(45) NOT NULL,
  `date_of_birth` date DEFAULT NULL,
  `phone` varchar(45) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `eligible_for_free_delivery` tinyint(4) NOT NULL DEFAULT '1',
  `eligible_for_lifetime_free_delivery` tinyint(4) NOT NULL DEFAULT '0',
  `status` varchar(45) NOT NULL DEFAULT 'ACTIVE',
  `activation_number` int(11) NOT NULL DEFAULT '0',
  `registration_date` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username_UNIQUE` (`username`),
  KEY `user_username_idx` (`username`),
  KEY `user_status_idx` (`status`),
  KEY `user_registration_date_idx` (`registration_date`)
) ENGINE=InnoDB AUTO_INCREMENT=750 DEFAULT CHARSET=latin1;
