  `id` int(11) NOT NULL AUTO_INCREMENT,
  `subject` varchar(128) DEFAULT NULL,
  `message` varchar(2048) DEFAULT NULL,
  `message_time` datetime NOT NULL,
  `read` tinyint(4) NOT NULL DEFAULT '0',
